// pixels はファミコンの色番号 (NES_PALETTE の添字)、TRANSPARENT は透明。

pub const TRANSPARENT: u8 = 0xFF;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Layer {
    Sprite,
    Bg, // 背景 (竜王 第2形態のみ)。スプライトより奥に表示される
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SpritePart {
    pub layer: Layer,
    pub tile: u8,     // ゲーム内のタイル番号
    pub pattern: u16, // ENEMY_TILE_PATTERNS のキー
    pub x: u8,        // 画面上の表示座標 (ゲームと同じ位置)
    pub y: u8,
    pub palette: u8, // Sprite は EnemySprite::palette、Bg は bg_palette の添字
    pub flip_h: bool,
    pub flip_v: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct EnemySprite {
    pub id: u8,
    pub name: &'static str,
    pub mirror: bool,                     // 他の敵の配置を左右反転して使っている
    pub palette: [[u8; 3]; 4],            // スプライト用 4 パレット x 3 色 (色番号)。色0 は透明
    pub bg_palette: Option<[[u8; 3]; 4]>, // 背景用 (竜王 第2形態のみ)
    pub parts: &'static [SpritePart],     // 先頭ほど手前に表示される
    pub x: u8,                            // pixels の左上の画面座標
    pub y: u8,
    pub width: u8,
    pub height: u8,
    pub pixels: &'static [u8], // 行優先 (index = y * width + x)
}

pub fn enemy_tile_pattern(pattern: u16) -> Option<&'static [u8; 64]> {
    ENEMY_TILE_PATTERNS
        .iter()
        .find(|(t, _)| *t == pattern)
        .map(|(_, p)| p)
}

pub fn enemy_pixel_rgb(color: u8) -> Option<(u8, u8, u8)> {
    (color != TRANSPARENT).then(|| NES_PALETTE[(color & 0x3F) as usize])
}

